// spec: specs/settings.md §1 · кейсы .qa/tests/settings/set-01…set-03 · seed: tests/seed.admin.spec.ts
// #61c0f4 (עבר QA 19.11): /settings ← «פרטי העסק» ← «ח.פ. / עוסק מורשה» (#business-tax-id) — только цифры (ошибка при сохранении
//   «ח.פ. / ת.ז. יכול לכלול ספרות בלבד», запрос не уходит), maxlength 15, необязательное; значение показывается в תעודת משלוח #504
//   под «באנגו דלי» (экран и печать); пусто — строки нет и пустой строки нет. Изоляция: dist2 (второй מפיץ, auth/dist2.json)
//   не видит значение admin, PATCH distributors?id=eq.<admin> из dist2 меняет 0 строк.
// МЕНЯЕТ ДАННЫЕ бизнеса admin (ח.פ.) → @data; serial; исходное значение читается в beforeAll и ВОЗВРАЩАЕТСЯ в afterAll (через UI).
// קבלה с ח.פ. не автоматизируется: требует нового утверждённого заказа (снимок на момент «אשר הזמנה») — неудаляемые хвосты на каждый прогон.
import { test, expect, Page, Browser } from '@playwright/test';
import { authFile, rest } from '../customers-pricing/_customers';

test.describe.configure({ mode: 'serial' });

const DN504 = '/delivery/6f797bf5-1ef8-44eb-8ad5-073e0b0f341e';
const BRAND = 'באנגו דלי';
const TAX = '900123456';
const LABEL = 'ח.פ. / עוסק מורשה';
const ERR = 'ח.פ. / ת.ז. יכול לכלול ספרות בלבד';
const BIDI = /[‎‏‪-‮⁦-⁩]/g;
let initial = '';

const taxInput = (page: Page) => page.locator('#business-tax-id');
/** Кнопка «שמירה» карточки «פרטי העסק» — ближайший предок поля, в котором есть такая кнопка. */
const saveBtn = (page: Page) => taxInput(page).locator('xpath=ancestor::*[.//button[normalize-space()="שמירה"]][1]').getByRole('button', { name: 'שמירה' });

async function openSettings(page: Page) {
  await page.goto('/settings');
  await expect(page.getByRole('heading', { level: 1, name: 'הגדרות' })).toBeVisible({ timeout: 30_000 });
  await expect(page.locator('#business-name'), 'данные бизнеса загружены').toHaveValue(/.+/, { timeout: 30_000 });
}

async function saveTaxId(page: Page, value: string) {
  await taxInput(page).fill(value);
  const saved = page.waitForResponse((r) => r.request().method() !== 'GET' && /\/rest\/v1\//.test(r.url()) && r.ok(), { timeout: 20_000 });
  await saveBtn(page).click();
  await saved;
}

/** Строка ח.פ. и название бизнеса в шапке תעודת משלוח при текущем media (видимые элементы). */
const dnHeader = (page: Page) => page.evaluate(({ brand }) => {
  const strip = (s: string) => s.replace(/[‎‏‪-‮⁦-⁩]/g, '').replace(/\s+/g, ' ').trim();
  const vis = [...document.querySelectorAll('body *')].filter((e) => (e as HTMLElement).checkVisibility());
  const leaf = (re: RegExp) => vis.filter((e) => re.test(strip(e.textContent || '')) && ![...e.children].some((c) => re.test(strip(c.textContent || ''))));
  const brandEl = leaf(new RegExp(`^${brand}$`))[0];
  const taxEl = leaf(/^ח\.פ\. \/ עוסק מורשה:/)[0];
  const rect = (e?: Element) => { if (!e) return null; const r = e.getBoundingClientRect(); return { l: r.left, r: r.right, t: r.top, b: r.bottom }; };
  const head = brandEl?.parentElement;
  return {
    brand: rect(brandEl), tax: rect(taxEl), taxText: taxEl ? strip(taxEl.textContent || '') : null,
    emptyChildren: head ? [...head.children].filter((c) => !strip(c.textContent || '')).length : -1,
    bodyHasLabel: strip(document.body.innerText).includes('ח.פ. / עוסק מורשה'),
  };
}, { brand: BRAND });

async function openDn(page: Page) {
  await page.goto(DN504);
  await expect(page.getByRole('heading', { level: 1, name: 'תעודת משלוח · הזמנה #504' })).toBeVisible({ timeout: 30_000 });
  await expect(page.locator('svg[data-barcode]').first()).toBeAttached({ timeout: 20_000 });
}

/** ח.פ. показан под названием бизнеса (тот же правый край), либо — для null — строки и пустого элемента нет. Экран и печать. */
async function expectDn(page: Page, value: string | null) {
  await openDn(page);
  for (const media of ['screen', 'print'] as const) {
    await page.emulateMedia({ media });
    const h = await dnHeader(page);
    expect(h.brand, `[${media}] название бизнеса видно`).not.toBeNull();
    if (value === null) {
      expect(h.tax, `[${media}] строки ח.פ. нет`).toBeNull();
      expect(h.bodyHasLabel, `[${media}] подписи «${LABEL}» нет в документе`).toBe(false);
      if (media === 'print') expect(h.emptyChildren, `[${media}] пустого элемента в шапке нет`).toBe(0);
    } else {
      expect(h.taxText, `[${media}]`).toBe(`${LABEL}: ${value}`);
      expect(h.tax!.t, `[${media}] ח.פ. под названием`).toBeGreaterThanOrEqual(h.brand!.b - 1);
      if (media === 'print') expect(Math.abs(h.tax!.r - h.brand!.r), `[${media}] общий правый край с названием (±2px)`).toBeLessThanOrEqual(2);
      else expect(Math.min(h.tax!.r, h.brand!.r) - Math.max(h.tax!.l, h.brand!.l), `[${media}] строки в одной колонке`).toBeGreaterThan(0);
    }
  }
  await page.emulateMedia({ media: 'screen' });
}

async function readInitial(browser: Browser, baseURL: string | undefined) {
  const ctx = await browser.newContext({ storageState: authFile('admin'), baseURL, locale: 'he-IL', viewport: { width: 1440, height: 900 } });
  try {
    const page = await ctx.newPage();
    await openSettings(page);
    return await taxInput(page).inputValue();
  } finally { await ctx.close(); }
}

test.describe('הגדרות ← פרטי העסק: ח.פ. / עוסק מורשה (#61c0f4)', () => {
  test.use({ storageState: authFile('admin') });

  test.beforeAll(async ({ browser, baseURL }) => { initial = await readInitial(browser, baseURL); });

  test.afterAll(async ({ browser, baseURL }) => {
    // вернуть исходное значение (в начале сессии QA — пусто)
    const ctx = await browser.newContext({ storageState: authFile('admin'), baseURL, locale: 'he-IL', viewport: { width: 1440, height: 900 } });
    try {
      const page = await ctx.newPage();
      await openSettings(page);
      if ((await taxInput(page).inputValue()) !== initial) await saveTaxId(page, initial);
      await page.reload();
      await expect(page.locator('#business-name')).toHaveValue(/.+/, { timeout: 30_000 });
      await expect(taxInput(page), 'исходное значение ח.פ. возвращено').toHaveValue(initial);
    } finally { await ctx.close(); }
  });

  test('ספרות בלבד: אותיות/רווחים — שגיאה «ח.פ. / ת.ז. יכול לכלול ספרות בלבד» בשמירה, שום בקשת כתיבה לא יוצאת, הערך לא נשמר #61c0f4 @desktop @data', async ({ page }) => {
    await openSettings(page);
    const writes: string[] = [];
    page.on('request', (r) => { if (r.method() !== 'GET' && /\/rest\/v1\//.test(r.url())) writes.push(`${r.method()} ${r.url()}`); });
    await taxInput(page).fill('12 34abc');
    await saveBtn(page).click();
    await expect(page.getByText(ERR, { exact: true })).toBeVisible();
    await expect(taxInput(page)).toHaveAttribute('aria-invalid', 'true');
    expect(writes, 'при ошибке валидации запись не отправлялась').toEqual([]);
    await page.reload();
    await expect(page.locator('#business-name')).toHaveValue(/.+/, { timeout: 30_000 });
    await expect(taxInput(page), 'значение с буквами не сохранено').toHaveValue(initial);
  });

  test('עד 15 ספרות: maxlength=15 — הקלדה של 19 ספרות נחתכת ל-15 #61c0f4 @desktop @data', async ({ page }) => {
    await openSettings(page);
    await expect(taxInput(page)).toHaveAttribute('maxlength', '15');
    await taxInput(page).fill('');
    await taxInput(page).pressSequentially('1234567890123456789');
    await expect(taxInput(page)).toHaveValue('123456789012345');
    await page.reload(); // ничего не сохраняем
  });

  test('שדה לא חובה: שמירה עם ערך ריק עוברת בלי שגיאה, ובתעודת משלוח (מסך והדפסה) אין שורת ח.פ. ואין שורה ריקה #61c0f4 @desktop @data', async ({ page }) => {
    await openSettings(page);
    await saveTaxId(page, '');
    await expect(page.getByText(ERR, { exact: true })).toHaveCount(0);
    await page.reload();
    await expect(page.locator('#business-name')).toHaveValue(/.+/, { timeout: 30_000 });
    await expect(taxInput(page)).toHaveValue('');
    await expectDn(page, null);
  });

  test('שמירת ספרות: הערך נשמר אחרי רענון ומוצג בתעודת משלוח #504 מתחת ל«באנגו דלי» — מסך והדפסה #61c0f4 @desktop @data', async ({ page }) => {
    await openSettings(page);
    await saveTaxId(page, TAX);
    await page.reload();
    await expect(page.locator('#business-name')).toHaveValue(/.+/, { timeout: 30_000 });
    await expect(taxInput(page), 'значение сохранено').toHaveValue(TAX);
    await expectDn(page, TAX);
  });

  test('בידוד בין מפיצים: dist2 לא רואה את ה-ח.פ. של admin, ו-PATCH על העסק של admin משנה 0 שורות #61c0f4 @desktop @data', async ({ page, browser, baseURL }) => {
    // id бизнеса admin — из его же сессии (RLS отдаёт только свой)
    await openSettings(page);
    await expect(taxInput(page)).toHaveValue(TAX);
    const own = await rest(page, 'GET', 'distributors?select=id,tax_id');
    expect(own.status).toBe(200);
    const adminRow = (own.json as { id: string; tax_id: string | null }[]).find((r) => r.tax_id === TAX);
    expect(adminRow, 'строка бизнеса admin с ח.פ. найдена').toBeTruthy();

    const ctx = await browser.newContext({ storageState: authFile('dist2'), baseURL, locale: 'he-IL', viewport: { width: 1440, height: 900 } });
    try {
      const d2 = await ctx.newPage();
      await openSettings(d2);
      await expect(taxInput(d2), 'dist2 не видит ח.פ. admin в своих настройках').not.toHaveValue(TAX);
      const seen = await rest(d2, 'GET', 'distributors?select=id,tax_id');
      expect((seen.json as { id: string; tax_id: string | null }[]).map((r) => r.id), 'dist2 не видит бизнес admin').not.toContain(adminRow!.id);
      const patch = await rest(d2, 'PATCH', `distributors?id=eq.${adminRow!.id}`, { tax_id: '111111111' });
      expect([200, 204], `PATCH из dist2: статус ${patch.status}`).toContain(patch.status);
      expect(patch.json ?? [], 'PATCH чужого бизнеса изменил 0 строк').toEqual([]);
    } finally { await ctx.close(); }

    const after = await rest(page, 'GET', `distributors?select=tax_id&id=eq.${adminRow!.id}`);
    expect((after.json as { tax_id: string }[])[0].tax_id, 'ח.פ. admin не изменился').toBe(TAX);
  });
});
